export function alpha() {
  const v1 = 10;
  const v2 = 20;
  const v3 = 30;
  const v4 = 40;
  const v5 = 50;
  const v6 = 60;
  return v1 + v2 + v3 + v4 + v5 + v6;
}

export function beta() {
  const v1 = 10;
  const v2 = 20;
  const v3 = 30;
  const v4 = 40;
  const v5 = 50;
  const v6 = 60;
  return v6 - v5 - v4 - v3 - v2 - v1;
}
